import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);

	await t.notThrowsAsync(limit.onIdle());
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle resolves after running and queued tasks settle', async t => {
	const limit = pLimit(2);
	const order = [];

	const first = limit(async () => {
		await delay(50);
		order.push('first');
	});
	const second = limit(async () => {
		await delay(10);
		order.push('second');
	});
	const third = limit(async () => {
		await delay(10);
		order.push('third');
	});

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	t.deepEqual(order.sort(), ['first', 'second', 'third']);

	await Promise.all([first, second, third]);
});

test('onIdle supports multiple waiters', async t => {
	const limit = pLimit(1);

	const task = limit(() => delay(30));

	const first = limit.onIdle();
	const second = limit.onIdle();
	const third = limit.onIdle();

	await Promise.all([first, second, third]);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await task;
});

test('onIdle waiters are released when a job rejects', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const task = limit(async () => {
		await delay(20);
		throw error;
	});

	// Observe the rejection so it does not become an unhandled rejection.
	const observedTask = task.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then

	const waiter = limit.onIdle();

	await t.notThrowsAsync(waiter);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.throwsAsync(Promise.resolve(task), {is: error});
	await observedTask;
});

test('reserved slots count as active for onIdle', async t => {
	const limit = pLimit(1);

	const first = limit(async () => {
		await delay(10);
	});

	// These become reserved slots when concurrency allows, and queued otherwise.
	const second = limit(() => delay(10));
	const third = limit(() => delay(10));

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all([first, second, third]);
});

test('onIdle does not report idle early when a resolving job enqueues another job', async t => {
	const limit = pLimit(1);
	let enqueued = false;

	const first = limit(async () => {
		await delay(10);
	});

	const second = limit(async () => {
		// Enqueue a follow-up job while this job is still running.
		limit(() => {
			enqueued = true;
		});
	});

	const waiter = limit.onIdle();

	await waiter;

	t.true(enqueued);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all([first, second]);
});

test('clearQueue releases onIdle waiters when nothing is active under rejectOnClear: false', async t => {
	const limit = pLimit(1);
	const running = limit(() => delay(40));

	// Under rejectOnClear: false these discarded promises stay unresolved.
	limit(() => delay(10));
	limit(() => delay(10));

	t.is(limit.pendingCount, 2);

	limit.clearQueue();

	await t.notThrowsAsync(limit.onIdle());
	t.is(limit.pendingCount, 0);

	await running;
});

test('clearQueue does not release onIdle waiters while jobs are still active', async t => {
	const limit = pLimit(1);
	let settled = false;
	const running = limit(async () => {
		await delay(30);
		settled = true;
	});

	limit(() => delay(10));
	limit(() => delay(10));

	limit.clearQueue();

	let idle = false;
	const waiter = (async () => {
		await limit.onIdle();
		idle = true;
	})();

	await delay(5);
	t.false(idle);
	t.false(settled);

	await waiter;
	t.true(settled);

	await running;
});

test('onIdle works for the limitFunction wrapper', async t => {
	const limitedFunction = limitFunction(async value => {
		await delay(10);
		return value * 2;
	}, {concurrency: 1});

	const first = limitedFunction(1);
	const second = limitedFunction(2);
	const third = limitedFunction(3);

	await limitedFunction.onIdle();

	t.deepEqual(await Promise.all([first, second, third]), [2, 4, 6]);
});

test('limitFunction onIdle resolves immediately when idle', async t => {
	const limitedFunction = limitFunction(() => delay(10), {concurrency: 1});

	await t.notThrowsAsync(limitedFunction.onIdle());
});

